<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import {onLoad,onShow,onHide,onUnload,onBackPress} from '@dcloudio/uni-app'
import {useMessage,useToast} from 'wot-design-uni'
import {closetApi,fieldLabels,type Garment,type ClosetTask} from '../../services/api'
import {closetTools} from '../../services/closet'
import {quickApi} from '../../services/quickIntake'
import {batchApi} from '../../services/batches'
import {useClosetStore} from '../../stores/closet'
import {useProcessingStore} from '../../stores/processing'
import {metadataPatch,rebaseMetadata,type MetadataField} from '../../domain/metadata'
import {createUuid} from '../../domain/id'
import {isProcessing,blocksConfirmation,workflowSummary,generatedImages,imageLabels,orderedTasks} from '../../domain/workflow'
import AuthImage from '../../components/AuthImage.vue'
import GarmentMetadataFields from '../../components/closet/GarmentMetadataFields.vue'
import GarmentProcessingStatus from '../../components/closet/GarmentProcessingStatus.vue'
import GarmentEdgeHelp from '../../components/closet/GarmentEdgeHelp.vue'
import TaskProgress from '../../components/closet/TaskProgress.vue'
import SimilarGarments from '../../components/closet/SimilarGarments.vue'
import WearHistory from '../../components/closet/WearHistory.vue'
import FloatingPager from '../../components/closet/FloatingPager.vue'
import {errorText,wardrobe,pending,openAdd,openBatch,outfitWith} from '../../components/closet/navigation'
const closet=useClosetStore(),processingStore=useProcessingStore(),message=useMessage(),toast=useToast()
const id=ref(''),queryTask=ref(''),garment=ref<Garment|null>(null),task=ref<ClosetTask|null>(null),imageTask=ref<ClosetTask|null>(null),parentTask=ref<ClosetTask|null>(null),baseline=ref<Garment|null>(null)
const source=ref<{batchId?:string;originalUrl?:string;previewUrl?:string;completion?:boolean}>({}),quickIntakeId=ref(''),schema=ref<MetadataField[]>([]),values=reactive<Record<string,string[]>>({}),selectedAssetId=ref(''),resetFields=ref<string[]>([]),confirmLayering=ref(false)
const loading=ref(true),busy=ref(''),error=ref(''),connectionError=ref(''),success=ref(''),panel=ref('result'),advanced=ref(''),originalOpen=ref(false),completed=ref(false),recognitionOpen=ref(false),recognitionHint=ref(''),enhanceOpen=ref(false),enhanceFeedback=ref(''),now=ref(Date.now())
const fields=Object.keys(fieldLabels) as (keyof typeof fieldLabels)[],layeringFields=['fit','thickness','wearingModes'],basicKeys=['category','primaryColor','patterns','seasons'],appearanceKeys=['secondaryColors','neckline','sleeveLength','garmentLength','closure','texture','styles']
const dirty=computed(()=>!!baseline.value&&(confirmLayering.value||resetFields.value.length>0||selectedAssetId.value!==baseline.value.displayAssetId||fields.some(key=>JSON.stringify(values[key]||[])!==JSON.stringify(baseline.value?.[key]||[]))))
const title=computed(()=>garment.value?.name||(garment.value?.category[0]?`${garment.value.primaryColor[0]||''}${garment.value.category[0]}`:'新上传衣物'))
const processing=computed(()=>isProcessing(task.value?.status)||isProcessing(garment.value?.taskStatus)||isProcessing(imageTask.value?.status)),currentTasks=computed(()=>orderedTasks(task.value,imageTask.value)),displayTask=computed(()=>currentTasks.value[0]||null),historyTasks=computed(()=>orderedTasks(task.value,imageTask.value,parentTask.value)),summary=computed(()=>garment.value?workflowSummary(garment.value,displayTask.value):null)
const results=computed(()=>quickIntakeId.value?(garment.value?.images||[]).filter(i=>['BASE','BASE_STICKER','AI_ENHANCED'].includes(i.kind)):generatedImages(imageTask.value||task.value))
const imageOptions=computed(()=>{if(!garment.value)return [];const g=garment.value;const all=[g.images.find(i=>i.url===g.sourceUrl),...(quickIntakeId.value?g.images:results.value),g.images.find(i=>i.id===g.displayAssetId)].filter((i):i is Garment['images'][number]=>!!i);return all.filter((i,n)=>all.findIndex(o=>o.id===i.id)===n)})
const selectedImage=computed(()=>imageOptions.value.find(i=>i.id===selectedAssetId.value)),preview=computed(()=>!quickIntakeId.value&&(processing.value||blocked.value)?garment.value?.sourceUrl:selectedImage.value?.url||garment.value?.displayUrl||garment.value?.sourceUrl)
const blocked=computed(()=>blocksConfirmation(garment.value?.assessment)),stickerPending=computed(()=>!!(garment.value?.imageProcessing?.stickerRequired&&!garment.value.imageProcessing.stickerReady))
const recoveryAsset=computed(()=>{const run=imageTask.value||task.value;if(!run)return null;const step=[...run.steps].reverse().find(s=>s.outputUrl&&['ENSURE_TRANSPARENCY','SEGMENT','GENERATE','STICKER'].includes(s.type||''));return run.assets?.find(a=>a.url===step?.outputUrl)||run.assets?.find(a=>a.url===run.inputUrl)||null})
const forceAsset=computed(()=>{const run=imageTask.value||task.value,check=[...(run?.steps||[])].reverse().find(s=>s.type==='ENSURE_TRANSPARENCY');return run?.assets?.find(a=>a.url===check?.inputUrl)||run?.assets?.find(a=>a.url===run.inputUrl)||recoveryAsset.value})
const transparency=computed(()=>[...(imageTask.value?.steps||[])].reverse().find(s=>s.transparency)?.transparency?.after),canApprove=computed(()=>!!transparency.value?.hasAlpha&&transparency.value.transparentRatio>=.005&&['USABLE','SUSPICIOUS'].includes(transparency.value.verdict))
const canConfirm=computed(()=>!processing.value&&schema.value.length>0&&!connectionError.value&&!blocked.value&&!stickerPending.value&&!!selectedAssetId.value),toolsLocked=computed(()=>processing.value||dirty.value||!!busy.value||garment.value?.status==='TRASHED'),editorLocked=computed(()=>!!busy.value||garment.value?.status==='TRASHED'||processing.value&&!quickIntakeId.value)
const layeringVerified=computed(()=>layeringFields.every(key=>(garment.value?.overrides[key]||[]).length&&JSON.stringify(values[key]||[])===JSON.stringify(garment.value?.overrides[key]||[])))
const basicSchema=computed(()=>schema.value.filter(f=>basicKeys.includes(f.key))),layeringSchema=computed(()=>schema.value.filter(f=>layeringFields.includes(f.key))),advancedSchema=computed(()=>schema.value.filter(f=>!basicKeys.includes(f.key)&&!layeringFields.includes(f.key)&&(advanced.value==='appearance'?appearanceKeys.includes(f.key):!appearanceKeys.includes(f.key))))
const detailTags=computed(()=>[...new Set(['category','primaryColor','patterns','seasons','styles'].flatMap(k=>values[k]||[]))].slice(0,8))
const pageTitle=computed(()=>completed.value?'已放进衣柜':panel.value==='metadata'?'编辑衣物资料':panel.value==='images'?'调整展示图片':panel.value==='history'?'处理记录':processing.value?'正在识别与整理':blocked.value?'先解决照片问题，再继续入柜':stickerPending.value?'图片已保留，贴纸还差一步':garment.value?.status==='ACTIVE'?title.value:garment.value?.status==='TRASHED'?'衣物已移入回收站':'识别与整理结果')
const pageSubtitle=computed(()=>panel.value==='metadata'?'按需修改，未知可留空。保存后返回结果，无需重新识别。':panel.value==='images'?'对照原图选择展示图片，需要时重新处理衣物边缘。':panel.value==='history'?'任务与图片保留，展示服务端的实际处理状态。':completed.value?'图片与衣物信息已保存，之后仍可继续修改。':processing.value?'处理在后台继续，你可以先离开，回来后继续。':blocked.value?'当前照片无法确认单件衣物，已填写的信息与原图都保留。':stickerPending.value?'可继续本地处理，也可以明确选择暂用原图入柜。':quickIntakeId.value?'图片保存后自动入柜，可随时调整展示图或编辑资料。':'确认入柜即可，需要时再调整图片或编辑资料。')
const reasonLabels:Record<string,string>={FOREGROUND_TOUCHES_IMAGE_EDGE:'衣物或残留像素接触画面边缘',FRAGMENTED_FOREGROUND:'检测到多个分离的区域',LARGE_SEMITRANSPARENT_AREA:'半透明区域较大',VERY_SMALL_FOREGROUND:'主体面积偏小',MOST_OF_IMAGE_IS_FOREGROUND:'主体占比过大',INSUFFICIENT_EXTERIOR_TRANSPARENCY:'画面外缘透明区域不足',NO_EFFECTIVE_TRANSPARENCY:'图片没有有效透明背景',NO_EFFECTIVE_FOREGROUND:'没有可用的衣物主体'}
let alive=false,epoch=0,delay=2000,timer:ReturnType<typeof setTimeout>|undefined,clock:ReturnType<typeof setInterval>|undefined,enhanceKey='',allowBack=false
const continuationKeys=new Map<string,string>()
let snapshot:{values:Record<string,string[]>;image:string;resets:string[];layering:boolean}|undefined
const neighbours=computed(()=>{const view=uni.getStorageSync('closet.wardrobe.view');const ids:string[]=view?.owner===closet.user?.username&&Date.now()-view.savedAt<1800000?view.ids||[]:[];const index=ids.indexOf(id.value);return index<0?null:{ids,index}})
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v))
function sync(g:Garment){baseline.value=clone(g);selectedAssetId.value=g.displayAssetId;resetFields.value=[];confirmLayering.value=false;for(const key of fields)values[key]=[...(g[key]||[])]}
async function load(reset=false){const mine=++epoch;try{const [g,definitions]=await Promise.all([closetApi.detail(id.value),schema.value.length?Promise.resolve(schema.value):closetApi.metadataFields()]);const taskId=queryTask.value||g.taskId,imageId=g.imageProcessing?.jobId;const [t,it]=await Promise.all([taskId?closetApi.task(taskId):null,imageId&&imageId!==taskId?closetApi.task(imageId):null]);const parent=(imageId===taskId?t:it)?.parentJobId;const p=parent?await closetApi.task(parent):null;if(!alive||mine!==epoch)return;const edited=dirty.value;garment.value=g;task.value=t;imageTask.value=imageId===taskId?t:it;parentTask.value=p;schema.value=definitions;if(reset||!baseline.value||!edited)sync(g);connectionError.value='';delay=2000;void closet.refreshCounts()}catch(e){if(alive&&mine===epoch){connectionError.value=errorText(e,'无法获取服务端状态。');delay=Math.min(delay*2,30000)}}finally{if(mine===epoch)loading.value=false}}
function poll(){clearTimeout(timer);if(alive&&(processing.value||connectionError.value))timer=setTimeout(async()=>{await load();poll()},delay)}
async function refresh(){await load();poll()}
function editField(key:string,next:string[]){values[key]=next;resetFields.value=resetFields.value.filter(k=>k!==key);if(layeringFields.includes(key))confirmLayering.value=false}
function restoreAutomatic(key:string){values[key]=[...(garment.value?.automatic[key]||[])];if(!resetFields.value.includes(key))resetFields.value.push(key);if(layeringFields.includes(key))confirmLayering.value=false}
function openPanel(next:string){snapshot={values:clone(values),image:selectedAssetId.value,resets:[...resetFields.value],layering:confirmLayering.value};panel.value=next;advanced.value='';uni.pageScrollTo({scrollTop:0,duration:0})}
function returnResult(cancel=false){if(cancel&&snapshot){Object.assign(values,snapshot.values);selectedAssetId.value=snapshot.image;resetFields.value=snapshot.resets;confirmLayering.value=snapshot.layering}panel.value='result';snapshot=undefined;uni.pageScrollTo({scrollTop:0,duration:0})}
async function confirm(title:string,msg:string,confirmButtonText='确定',cancelButtonText='取消'){try{await message.confirm({title,msg,confirmButtonText,cancelButtonText});return true}catch{return false}}
function patch(){const p=metadataPatch(schema.value,values,baseline.value||{},resetFields.value);if(confirmLayering.value)for(const key of layeringFields)p[key]=[...(values[key]||[])];return p}
async function save(confirming=false,fallback=false){if(!garment.value||!baseline.value||!schema.value.length||busy.value||processing.value&&!quickIntakeId.value)return false;busy.value=confirming?'confirm':'save';error.value='';try{let g=confirming?await closetApi.confirm(id.value,{revision:baseline.value.revision,assetId:fallback?garment.value.images.find(i=>i.url===garment.value?.sourceUrl)?.id:selectedAssetId.value,allowIncompleteSticker:fallback,fields:patch(),resetFields:[...resetFields.value]}):await closetApi.update(id.value,{revision:baseline.value.revision,fields:patch(),resetFields:[...resetFields.value]});if(!confirming&&(selectedAssetId.value!==g.displayAssetId||quickIntakeId.value&&panel.value==='images'))g=await closetApi.chooseDisplay(id.value,selectedAssetId.value,g.revision);garment.value=g;sync(g);success.value=confirming?fallback?'已暂用原图入柜，贴纸仍未完成，可稍后继续制作。':'已确认入柜，图片和信息已保存。':'修改已保存。';toast.success(success.value);if(confirming&&!fallback){completed.value=true;panel.value='result'}await closet.refreshCounts();return true}catch(e){error.value=errorText(e,'保存失败，你的输入仍保留。');return false}finally{busy.value=''}}
async function saveAndReturn(){if(!dirty.value||await save())returnResult()}
async function leave(){if(busy.value)return;if(dirty.value){if(!await confirm('离开前保存修改？','当前资料或展示图还有未保存的修改。','保存并离开','继续编辑'))return;if(!await save())return}allowBack=true;if(source.value.batchId)openBatch(source.value.batchId);else if(garment.value?.status==='ACTIVE')wardrobe();else pending()}
async function useOriginal(){if(await confirm('暂用上传原图入柜？','贴纸尚未完成。本次保存原图和信息，不会把中间结果标记成贴纸。以后可从衣物详情继续制作。','暂用原图入柜','继续制作贴纸'))await save(true,true)}
async function continueSticker(policy:'FORCE'|'REVIEWED'){const run=imageTask.value||task.value,asset=policy==='FORCE'?forceAsset.value:recoveryAsset.value;if(!run||!asset||processing.value||busy.value||connectionError.value)return;if(policy==='REVIEWED'&&!await confirm('已核对这张透明图片？','请先对照原图，确认衣物完整、背景已去除、没有明显杂物。继续后会实际制作白边贴纸，不再调用 AI。','确认并制作贴纸','返回检查'))return;if(dirty.value&&!await save())return;busy.value='continue';error.value='';const identity=`${run.id}:${asset.id}:${policy}`,key=continuationKeys.get(identity)||createUuid();continuationKeys.set(identity,key);try{const next=await closetApi.continueSticker(run.id,asset.id,policy,key);queryTask.value=next.id;task.value=next;processingStore.trackTask(next,true);continuationKeys.delete(identity);returnResult();await refresh()}catch(e){error.value=errorText(e,'本地处理提交失败，原图和修改已保留。')}finally{busy.value=''}}
async function reconcile(){if(!await confirm('核对当前服务端版本','保留你修改过的字段，更新未修改的字段。请核对服务端当前值后再主动保存。','保留输入并核对','返回编辑'))return;const old=baseline.value,input=clone(values),image=selectedAssetId.value,resets=[...resetFields.value];await load();if(!garment.value||!old||connectionError.value)return;Object.assign(values,rebaseMetadata(schema.value,input,old,garment.value));selectedAssetId.value=image===old.displayAssetId?garment.value.displayAssetId:image;resetFields.value=resets;for(const key of resets)values[key]=[...(garment.value.automatic[key]||[])];baseline.value=clone(garment.value);error.value='';success.value='输入已保留，请核对服务端当前值后保存。'}
async function run(mode:'recognize'|'reprocess'){if(toolsLocked.value)return;if(mode==='recognize'){recognitionOpen.value=true;return}if(await confirm('重新整理图片？','会分别调用识别和整理模型，各使用 1 次 AI 额度，共 2 次。已有人工修改和图片会保留。','提交真实任务'))await submitRun(mode)}
async function submitRun(mode:'recognize'|'reprocess'){if(!garment.value||toolsLocked.value)return;busy.value='retry';error.value='';try{const next=mode==='recognize'?await closetApi.recognize(id.value,recognitionHint.value.trim()):await closetApi.reprocess(id.value);queryTask.value=next.id;task.value=next;processingStore.trackTask(next,true);recognitionOpen.value=false;returnResult();await refresh()}catch(e){error.value=errorText(e,'任务提交失败。')}finally{busy.value=''}}
async function enhance(){if(!quickIntakeId.value||toolsLocked.value)return;busy.value='enhance';error.value='';try{enhanceKey||=createUuid();await quickApi.enhance(quickIntakeId.value,enhanceKey,enhanceFeedback.value);enhanceKey='';enhanceOpen.value=false;await refresh()}catch(e){error.value=errorText(e)}finally{busy.value=''}}
async function cancel(){const target=isProcessing(imageTask.value?.status)?imageTask.value:task.value;if(!target||busy.value||!await confirm('取消这次处理？','原图和已完成步骤的图片会保留。取消请求提交后，需要等待服务端终止任务。','取消处理','继续等待'))return;busy.value='cancel';try{await closetApi.cancel(target.id);await refresh()}catch(e){error.value=errorText(e,'取消失败。')}finally{busy.value=''}}
async function trash(){if(!garment.value||busy.value||!await confirm('移入回收站？',processing.value?'会先取消活动任务，等待终止后移入回收站。图片与历史保留，可以恢复。':'图片与处理历史会保留，可以在回收站恢复。','移入回收站'))return;busy.value='trash';try{if(processing.value)for(const taskId of [...new Set([garment.value.taskId,imageTask.value?.id].filter((v):v is string=>!!v))])await closetApi.cancelAndWait(taskId);const record=await closetApi.detail(id.value);await closetApi.trash(id.value,record.revision);allowBack=true;toast.success(`「${title.value}」已移入回收站，可在回收站恢复。`);void closet.refreshCounts();record.status==='ACTIVE'?wardrobe():pending()}catch(e){error.value=errorText(e)}finally{busy.value=''}}
async function restore(){if(!garment.value||busy.value)return;busy.value='restore';try{garment.value=await closetApi.restore(id.value,'DRAFT',garment.value.revision);sync(garment.value);await closet.refreshCounts()}catch(e){error.value=errorText(e)}finally{busy.value=''}}
async function favorite(){if(!garment.value||busy.value||dirty.value)return;busy.value='favorite';try{garment.value=await closetTools.basic(id.value,garment.value.revision,{favorite:!garment.value.favorite});sync(garment.value)}catch(e){error.value=errorText(e)}finally{busy.value=''}}
function fieldValue(key:string){return (values[key]||[]).join('、')||'未知'}
function step(delta:number){const next=neighbours.value?.ids[(neighbours.value?.index||0)+delta];if(next&&!toolsLocked.value)uni.redirectTo({url:'/pkg-closet/garment/index?id='+encodeURIComponent(next)})}
onLoad(q=>{id.value=String(q?.id||'');queryTask.value=String(q?.task||'');if(q?.batch)source.value.batchId=String(q.batch)})
onShow(async()=>{alive=true;clock=setInterval(()=>now.value=Date.now(),1000);if(!id.value){loading.value=false;connectionError.value='缺少衣物编号。';return}await Promise.all([load(),quickApi.provenance(id.value).then(v=>quickIntakeId.value=v.intakeId||'').catch(()=>{}),batchApi.provenance(id.value).then(v=>source.value={...source.value,...v}).catch(()=>{})]);poll()})
function stop(){alive=false;clearTimeout(timer);clearInterval(clock)}onHide(stop);onUnload(()=>{stop();epoch++})
onBackPress(()=>{if(allowBack)return false;if(busy.value)return true;if(panel.value!=='result'){returnResult(true);return true}if(dirty.value){void leave();return true}return false})
</script>
<template><view class="page closet-page">
 <wd-button type="text" @click="panel==='result'?leave():returnResult(true)">{{panel!=='result'?'返回处理结果':source.batchId?'返回本批次':garment?.status==='ACTIVE'?'返回衣柜':'所有未入柜衣物'}}</wd-button>
 <wd-skeleton v-if="loading" :row-col="[1,1,{height:'600rpx'},1,1,1]" animation="gradient"/>
 <view v-else-if="!garment" class="section"><wd-status-tip image="network" :tip="connectionError"/><wd-button @click="refresh">重试</wd-button></view>
 <template v-else>
 <view class="heading"><text class="title">{{pageTitle}}</text><text class="subtitle">{{pageSubtitle}}</text><view class="tags"><wd-tag>{{garment.status==='ACTIVE'?'已入柜':garment.status==='TRASHED'?'回收站':'尚未入柜'}}</wd-tag></view></view>
 <view v-if="connectionError" class="notice"><wd-notice-bar :text="`连接中断：${connectionError}。保留上次状态，正在重试。`" :scrollable="false" wrapable/><wd-button type="text" @click="refresh">重新连接</wd-button></view>
 <view v-if="error" class="notice"><wd-notice-bar :text="error+' 你的图片选择和表单输入仍保留。'" type="danger" :scrollable="false" wrapable/><wd-button type="text" @click="reconcile">核对最新版本</wd-button></view>
 <wd-notice-bar v-if="success&&!completed" class="notice" :text="success" type="info" :scrollable="false" wrapable/>
 <view v-if="completed" class="section"><view class="preview"><AuthImage :src="garment.displayUrl||preview" :width="960" previewable/></view><text class="section-title">{{title}}</text><text class="subtitle">{{fieldValue('patterns')}} · {{fieldValue('seasons')}}</text><view class="actions"><wd-button @click="wardrobe">查看衣柜</wd-button><wd-button plain @click="openAdd()">继续添加衣物</wd-button><wd-button type="text" @click="completed=false">查看衣物详情</wd-button></view></view>
 <template v-else>
 <template v-if="panel==='metadata'">
 <view class="section"><text class="section-title">这次录入的衣物</text><view class="small-preview"><AuthImage :src="preview" :width="640" previewable/></view><text class="subtitle">{{title}}</text><wd-button type="text" @click="originalOpen=true">查看上传原图</wd-button></view>
 <view class="section"><text class="section-title">衣物基本信息</text><GarmentMetadataFields :schema="basicSchema" :values="values" :garment="garment" :reset-fields="resetFields" :disabled="editorLocked" @edit="editField" @restore="restoreAutomatic"/><text class="section-title spaced">穿着建议</text><text class="subtitle">照片不能保证实际版型、厚薄和叠穿用途。不确定可留空，资料不足不会自动推断为适合叠穿。</text><GarmentMetadataFields :schema="layeringSchema" :values="values" :garment="garment" :reset-fields="resetFields" :disabled="editorLocked" @edit="editField" @restore="restoreAutomatic"/><view class="actions"><wd-checkbox :model-value="confirmLayering||layeringVerified" :disabled="editorLocked||!layeringFields.every(k=>values[k]?.length)||layeringVerified" @update:model-value="confirmLayering=!!$event">我已根据实物核对这些穿着建议</wd-checkbox></view><view class="actions"><wd-button size="small" plain @click="advanced='appearance'">更多外观资料</wd-button><wd-button size="small" plain @click="advanced='labels'">品牌、尺码与其他标签</wd-button></view></view>
 </template>
 <template v-else-if="panel==='images'">
 <view class="section"><text class="section-title">图片对照</text><text class="subtitle">{{stickerPending?'尚未贴纸化':'当前可用图片'}}</text><view v-for="image in results" :key="image.id" class="image-result"><text class="hint">{{imageLabels[image.kind]||'处理结果'}}</text><view class="preview"><AuthImage :src="image.url" :width="960" previewable/></view><text v-if="image.aiGenerated" class="hint">AI 生成，可能包含推测细节</text></view><wd-status-tip v-if="!results.length" image="content" tip="本次没有生成图片"/><text class="subtitle">上传原图</text><view class="preview"><AuthImage :src="garment.sourceUrl" :width="960" previewable/></view></view>
 <view class="section"><text class="section-title">衣柜展示图</text><wd-radio-group v-model="selectedAssetId" :disabled="editorLocked"><view v-for="image in imageOptions" :key="image.id" class="image-option"><view class="thumb"><AuthImage :src="image.url" :width="160"/></view><wd-radio :value="image.id">{{imageLabels[image.kind]||'处理图片'}}{{selectedAssetId===image.id?' · 已选':''}}</wd-radio><text v-if="image.aiGenerated" class="hint">AI 生成，可能包含推测细节</text></view></wd-radio-group><text class="section-title spaced">检查这些细节</text><text class="subtitle">衣物轮廓完整；颜色、花纹与原图一致；背景没有明显杂物。</text><GarmentEdgeHelp/><wd-button v-if="forceAsset&&!stickerPending" plain :disabled="toolsLocked" @click="continueSticker('FORCE')">边缘不满意，重新去背景</wd-button><text class="hint">本地处理，不使用 AI 额度</text><view class="actions"><wd-button plain :disabled="toolsLocked" @click="run('reprocess')">重新整理图片 · 2 次额度</wd-button><wd-button plain :disabled="toolsLocked" @click="run('recognize')">重新识别信息 · 1 次额度</wd-button></view></view>
 </template>
 <template v-else-if="panel==='history'"><GarmentProcessingStatus :garment-id="garment.id" :revision="garment.revision"/><TaskProgress v-for="run in historyTasks" :key="run.id" :task="run" :now="now"/><wd-status-tip v-if="!historyTasks.length" image="content" tip="本次没有处理任务"/></template>
 <template v-else>
 <view class="preview"><AuthImage :src="preview" :width="960" previewable/></view><text v-if="selectedImage?.aiGenerated" class="hint">AI 生成，可能包含推测细节</text><view class="actions"><wd-button size="small" plain @click="originalOpen=true">对照原图</wd-button><wd-button size="small" plain :disabled="editorLocked" @click="openPanel('images')">更换展示图</wd-button><wd-button size="small" type="text" @click="openPanel('history')">处理记录</wd-button></view>
 <view v-if="summary" class="section"><text class="section-title">{{summary.title}}</text><text class="subtitle">{{summary.description}}</text></view><wd-notice-bar v-for="(issue,index) in garment.issues" :key="index" class="notice" :text="issue.message" :scrollable="false" wrapable/><wd-notice-bar v-if="source.completion" class="notice" text="包含推测补全，请对照来源照片检查。" :scrollable="false" wrapable/>
 <template v-if="processing"><TaskProgress v-if="displayTask" :task="displayTask" :now="now"/><text class="subtitle">处理会在后台继续，你可以先离开，回来后继续。</text><view class="actions"><wd-button plain :disabled="!!busy||displayTask?.status==='CANCEL_REQUESTED'" @click="cancel">取消本次处理</wd-button></view></template>
 <view v-else-if="blocked" class="section"><text class="section-title">还不能确定要入柜哪一件</text><text class="subtitle">照片里有多件衣物。使用多件整理，分别处理每件衣物。</text><wd-button @click="openAdd('multiple')">转到多件录入</wd-button><text class="section-title spaced">只有一件，但模糊或被遮挡</text><text class="subtitle">重新录入清楚、完整的照片。原草稿与资料会保留。</text><wd-button plain @click="openAdd()">更换照片</wd-button><GarmentEdgeHelp/></view>
 <view v-else-if="stickerPending" class="section"><text class="section-title">继续这件衣物</text><text>推荐：完成贴纸</text><text class="subtitle">重新去背景与制作白边。本地处理，不使用 AI 额度。</text><wd-notice-bar v-if="transparency?.reasons.length" class="notice" :text="transparency.reasons.map(r=>reasonLabels[r]||'透明背景需要检查').join('；')" :scrollable="false" wrapable/><view class="stack"><wd-button :disabled="!forceAsset||!!busy||blocked||!!connectionError||garment.status==='TRASHED'" :loading="busy==='continue'" @click="continueSticker('FORCE')">重新抠图并制作贴纸</wd-button><wd-button v-if="canApprove" plain :disabled="!!busy||!!connectionError||garment.status==='TRASHED'" @click="continueSticker('REVIEWED')">已核对透明图，继续制作</wd-button><wd-button v-if="garment.status==='DRAFT'" plain :disabled="!!busy||blocked||!!connectionError||!schema.length" @click="useOriginal">暂用上传原图入柜</wd-button></view><GarmentEdgeHelp/></view>
 <view class="section"><text class="section-title">{{title}}</text><view class="tags"><wd-tag v-for="tag in detailTags" :key="tag" plain>{{tag}}</wd-tag></view><view class="actions"><wd-button v-if="garment.status==='ACTIVE'" @click="outfitWith(garment.id)">用它搭一套</wd-button><wd-button plain :disabled="editorLocked" @click="openPanel('metadata')">编辑资料</wd-button><wd-button v-if="garment.status!=='TRASHED'" plain :disabled="!!busy||dirty" @click="favorite">{{garment.favorite?'取消收藏':'加入收藏'}}</wd-button></view><text class="section-title spaced">衣物资料</text><view v-for="key in fields.filter(k=>!layeringFields.includes(k)&&(basicKeys.includes(k)||values[k]?.length))" :key="key" class="field-row"><text class="label">{{fieldLabels[key]}}</text><text>{{fieldValue(key)}}</text></view><text class="section-title spaced">穿着建议</text><wd-tag plain>{{layeringVerified?'已按实物核对':'照片推测'}}</wd-tag><view v-for="key in layeringFields" :key="key" class="field-row"><text class="label">{{key==='fit'?'版型':key==='thickness'?'厚薄':'用途'}}</text><text>{{fieldValue(key)}}</text></view><wd-button v-if="!layeringVerified&&garment.status!=='TRASHED'" type="text" @click="openPanel('metadata')">按实物核对，推荐会更准</wd-button></view>
 <view v-if="garment.status!=='TRASHED'" class="section"><text class="section-title">智能工具</text><view class="stack"><wd-button plain :disabled="toolsLocked" @click="run('recognize')">重新识别信息 · 1 次额度</wd-button><text class="hint">重新识别品类、颜色等资料，可补充说明；你改过的资料会保留</text><wd-button v-if="quickIntakeId" plain :disabled="toolsLocked" @click="enhanceOpen=true">增强图片 · 1 次额度</wd-button><wd-button v-else plain :disabled="toolsLocked" @click="run('reprocess')">重新整理图片 · 2 次额度</wd-button><text class="hint">AI 修复边缘、人物残留等问题，原图保留可回退；AI 生成可能包含推测细节。</text><wd-button v-if="forceAsset" plain :disabled="toolsLocked||!!connectionError" @click="continueSticker('FORCE')">重新去背景 · 免费</wd-button><text class="hint">边缘不满意时重新抠图并制作贴纸，本地完成</text><text v-if="dirty" class="hint">先保存当前修改，再使用这些工具。</text></view></view>
 <WearHistory v-if="garment.status==='ACTIVE'" :key="garment.id" :garment-id="garment.id"/><SimilarGarments v-if="garment.status!=='TRASHED'" :key="garment.id" :garment-id="garment.id" :draft="garment.status==='DRAFT'"/>
 <view class="actions"><wd-button v-if="garment.status==='TRASHED'" :loading="busy==='restore'" @click="restore">恢复到未入柜</wd-button><wd-button v-else type="error" plain :disabled="!!busy" @click="trash">移入回收站</wd-button></view>
 <FloatingPager v-if="neighbours&&!dirty&&!processing" :page="neighbours.index+1" :pages="neighbours.ids.length" previous-text="上一件" next-text="下一件" :busy="!!busy" @change="step"/>
 </template>
 <view v-if="panel==='metadata'||panel==='images'||dirty||garment.status==='DRAFT'" class="fixed-actions"><view class="row"><wd-button v-if="panel!=='result'" plain :disabled="!!busy" @click="returnResult(true)">取消修改</wd-button><wd-button v-if="panel==='metadata'||panel==='images'||dirty" :loading="busy==='save'" :disabled="editorLocked||!!connectionError" @click="saveAndReturn">保存修改</wd-button><wd-button v-if="panel==='result'&&garment.status==='DRAFT'" :disabled="!canConfirm||!!busy" :loading="busy==='confirm'" @click="save(true)">确认入柜</wd-button></view></view>
 </template>
 </template>
 <wd-popup v-model="originalOpen" position="bottom" closable><view class="sheet"><text class="sheet-title">原图与展示图对照</text><text class="subtitle">上传原图</text><view class="preview"><AuthImage :src="source.originalUrl||garment?.sourceUrl" :width="960" previewable/></view><text class="subtitle">当前展示图</text><view class="preview"><AuthImage :src="preview" :width="960" previewable/></view></view></wd-popup>
 <wd-popup :model-value="!!advanced" position="bottom" closable @close="advanced='' "><view v-if="garment" class="sheet"><text class="sheet-title">{{advanced==='appearance'?'更多外观资料':'品牌、尺码与其他标签'}}</text><GarmentMetadataFields :schema="advancedSchema" :values="values" :garment="garment" :reset-fields="resetFields" :disabled="editorLocked" @edit="editField" @restore="restoreAutomatic"/><view class="actions"><wd-button block @click="advanced=''">完成</wd-button></view></view></wd-popup>
 <wd-popup v-model="recognitionOpen" position="bottom" closable><view class="sheet"><text class="sheet-title">重新识别衣物信息</text><text class="subtitle">只更新自动识别资料，人工修改和展示图片会保留。</text><wd-textarea v-model="recognitionHint" label="这次识别哪件衣物（可选）" :maxlength="200" show-word-limit placeholder="例如：这是一件黑白拼接连衣裙；或只识别左侧外套。"/><text class="hint">可以补充实物结构，帮助区分拼色、假两件和分开的衣物；看不清的标签信息仍会留空。</text><view class="actions"><wd-button block :loading="busy==='retry'" @click="submitRun('recognize')">提交识别 · 1 次额度</wd-button></view></view></wd-popup>
 <wd-popup v-model="enhanceOpen" position="bottom" closable><view class="sheet"><text class="sheet-title">独立增强图片</text><text class="subtitle">使用一次增强额度。原图、基础图和历史结果保留，成功后会采用新图；可在展示图片中回退。AI 生成可能包含推测细节。</text><wd-textarea v-model="enhanceFeedback" :maxlength="1000" placeholder="可选：描述人物残留、边缘损坏、文字错误等问题"/><view class="actions"><wd-button block :loading="busy==='enhance'" @click="enhance">开始增强</wd-button></view></view></wd-popup><wd-message-box/><wd-toast/>
</view></template>
<style lang="scss" scoped>@import '../../components/closet/closet.scss';.small-preview{height:320rpx}.spaced{margin-top:40rpx}.image-option{padding:24rpx 0;border-bottom:2rpx solid $line}.thumb{width:160rpx;height:160rpx;margin-bottom:16rpx}.image-result{margin:24rpx 0}.fixed-actions .row>*{flex:1}</style>
